window.TIN_QUESTIONS = [{"id":1,"type":"mcq","question":"Trí tuệ nhân tạo là gì?","options":{"A":"Một loại robot có khả năng tự học và tự nâng cấp","B":"Hệ thống do con người xây dựng và lập trình nhằm giúp máy tính có thể thực hiện các hành vi thông minh như con người.","C":"Một loại máy tính có khả năng thực hiện các tác vụ như làm việc văn phòng và lập trình","D":"Một phần mềm giúp người dùng tạo ra hình ảnh"},"answer":"B"},{"id":2,"type":"mcq","question":"Hầu hết các hệ thống Trí tuệ nhân tạo đang được ứng dụng phổ biến hiện nay (như trợ lý ảo, dịch máy, nhận dạng ảnh) thuộc loại nào sau đây?","options":{"A":"AI hẹp (ANI).","B":"AI tổng quát (AGI).","C":"Siêu AI (ASI).","D":"AI toàn năng."},"answer":"A"},{"id":3,"type":"mcq","question":"Khả năng học của AI là gì?","options":{"A":"Trích rút được thông tin từ dữ liệu để học và tích lũy tri thức","B":"Vận dụng tri thức và logic để đưa ra quyết định hoặc giải quyết vấn đề","C":"Đọc, hiểu, diễn giải và tạo ra văn bản tương tự như con người.","D":"Vận dụng tri thức, nhận thức, suy luận, khả năng hiểu ngôn ngữ để giải quyết vấn đề."},"answer":"A"},{"id":4,"type":"mcq","question":"Phương án nào sau đây là thành tựu của lĩnh vực thị giác máy tính?","options":{"A":"Hệ thống nhận dạng hình ảnh và video.","B":"Hệ thống phân tích dữ liệu.","C":"Hệ thống lắp ráp tự động.","D":"Hệ thống tưới tiêu tự động."},"answer":"A"},{"id":5,"type":"mcq","question":"Phương án nào sau đây là ứng dụng của AI trong lĩnh vực thị giác máy tính?","options":{"A":"Nhận dạng giọng nói.","B":"Nhận dạng chữ viết tay.","C":"Trợ lý ảo","D":"Kiểm tra lỗi chính tả."},"answer":"B"},{"id":6,"type":"mcq","question":"Phương án nào sau đây không phải là ứng dụng của AI trong lĩnh vực y tế?","options":{"A":"Robot hỗ trợ phẫu thuật.","B":"Chẩn đoán bệnh bằng hình ảnh chụp cắt lớp vi tính.","C":"Theo dõi sức khoẻ.","D":"Phân tích dữ liệu thị trường."},"answer":"D"},{"id":7,"type":"mcq","question":"AI (ANI) yếu được thiết kế để làm gì?","options":{"A":"Thực hiện các nhiệm vụ không cần sự can thiệp của con người.","B":"Tương tác tự nhiên với con người mà không cần trợ giúp.","C":"Giải quyết các vấn đề phức tạp trong nhiều lĩnh vực khác nhau.","D":"Được thiết kế để thực hiện một nhiệm vụ cụ thể, giới hạn"},"answer":"D"},{"id":8,"type":"mcq","question":"Lĩnh vực nào liên quan đến việc thu nhận và phân tích nhận dạng hình ảnh?","options":{"A":"Học máy.","B":"Xử lý ngôn ngữ tự nhiên.","C":"Thị giác máy tính.","D":"AI tạo sinh."},"answer":"C"},{"id":9,"type":"mcq","question":"Khả năng hiểu ngôn ngữ của AI là gì?","options":{"A":"Trích rút được thông tin từ dữ liệu để học và tích lũy tri thức","B":"Vận dụng tri thức và logic để đưa ra quyết định hoặc giải quyết vấn đề","C":"Đọc, hiểu, diễn giải và tạo ra văn bản tương tự như con người.","D":"Vận dụng tri thức, nhận thức, suy luận, khả năng hiểu ngôn ngữ để giải quyết vấn đề."},"answer":"C"},{"id":10,"type":"mcq","question":"Khả năng suy luận của AI là gì?","options":{"A":"Trích rút được thông tin từ dữ liệu để học và tích lũy tri thức","B":"Vận dụng tri thức và logic để đưa ra quyết định hoặc giải quyết vấn đề","C":"Đọc, hiểu, diễn giải và tạo ra văn bản tương tự như con người.","D":"Vận dụng tri thức, nhận thức, suy luận, khả năng hiểu ngôn ngữ để giải quyết vấn đề."},"answer":"B"},{"id":11,"type":"mcq","question":"Một hệ thống thư điện tử tự động nhận diện và chuyển các thư có dấu hiệu quảng cáo lừa đảo vào hòm thư rác sau khi được cung cấp hàng nghìn bức thư mẫu để huấn luyện. Hệ thống này thể hiện rõ nhất đặc trưng nào sau đây của Trí tuệ nhân tạo?","options":{"A":"Khả năng thể hiện cảm xúc tự nhiên.","B":"Khả năng tự ý thức về sự tồn tại của hệ thống.","C":"Khả năng học (Machine Learning) từ dữ liệu mẫu.","D":"Khả năng điều khiển các thiết bị ngoại vi trong thực tế."},"answer":"C"},{"id":12,"type":"mcq","question":"Phát biểu nào sau đây là đúng khi nói về Trí tuệ nhân tạo (AI)?","options":{"A":"Hệ thống ANI được xây dựng để nhận dạng khuôn mặt có thể hoạt động tốt để phân loại các đối tượng khác trong ảnh.","B":"Khả năng giải quyết vấn đề của AI là khả năng trích rút được thông tin từ dữ liệu để học và tích luỹ tri thức.","C":"Các hệ thống AI tính đến năm nay đều thuộc loại AGI (AI tổng quát).","D":"Khả năng suy luận của AI là khả năng vận dụng tri thức và logic để đưa ra quyết định hoặc giải quyết vấn đề."},"answer":"D"},{"id":13,"type":"mcq","question":"Một trợ lý ảo phổ biến trên điện thoại thông minh (như Siri, Google Assistant) thường không hỗ trợ trực tiếp chức năng nào sau đây?","options":{"A":"Nhận dạng lệnh thoại để tạo sự kiện trong lịch làm việc.","B":"Trực tiếp đo đạc và phân tích các chỉ số sinh học chuyên sâu như xét nghiệm máu.","C":"Tìm kiếm thông tin và giải đáp thắc mắc bằng giọng nói của người dùng.","D":"Điều khiển bật/tắt các ứng dụng và thiết bị thông minh kết nối cùng mạng."},"answer":"B"},{"id":14,"type":"mcq","question":"Công nghệ nhận dạng khuôn mặt thường không được áp dụng trực tiếp cho mục đích nào sau đây?","options":{"A":"Xử lý và phân tích ngữ pháp trong một văn bản tiếng Việt.","B":"Mở khóa màn hình thiết bị di động cá nhân.","C":"Xác thực sinh trắc học khi thực hiện giao dịch ngân hàng trực tuyến.","D":"Quản lý điểm danh tự động cho học sinh, nhân viên tại cổng ra vào."},"answer":"A"},{"id":15,"type":"mcq","question":"Một ứng dụng học ngoại ngữ có tính năng yêu cầu người học phát âm một câu thoại, sau đó ghi âm, phân tích ngữ điệu và chỉ ra cụ thể từ nào phát âm chưa chuẩn để chấm điểm. Tính năng này đã kết hợp các công nghệ chủ yếu nào của Trí tuệ nhân tạo?","options":{"A":"Công nghệ nhận dạng vân tay và mã hóa dữ liệu đường truyền.","B":"Công nghệ nhận dạng giọng nói và xử lý ngôn ngữ tự nhiên.","C":"Công nghệ thị giác máy tính và nhận dạng khuôn mặt người học.","D":"Công nghệ định vị GPS và truyền thông qua Internet vạn vật (IoT)."},"answer":"B"},{"id":16,"type":"mcq","question":"Một trang thương mại điện tử muốn nâng cao trải nghiệm mua sắm bằng cách tự động đề xuất các mặt hàng phù hợp với sở thích của từng khách hàng dựa trên lịch sử xem hàng và giỏ hàng trước đó. Để giải quyết bài toán này, doanh nghiệp nên ứng dụng đặc trưng nào sau đây của AI?","options":{"A":"Khả năng tự động hóa dây chuyền sản xuất cơ khí.","B":"Khả năng học máy (Machine Learning) từ dữ liệu hành vi người dùng.","C":"Khả năng kết nối mạng không dây diện rộng qua Internet vạn vật (IoT).","D":"Khả năng nén và mã hóa tệp dữ liệu dung lượng lớn."},"answer":"B"},{"id":17,"type":"mcq","question":"Một học sinh chuẩn bị bài thuyết trình lịch sử và muốn sử dụng công cụ AI tạo sinh (như ChatGPT) để tổng hợp tư liệu. Để đảm bảo tính chính xác và tránh rủi ro về mặt thông tin do hiện tượng 'ảo giác' của AI gây ra, học sinh này nên thực hiện hành động nào sau đây?","options":{"A":"Sao chép trực tiếp toàn bộ nội dung do AI trả về để đảm bảo tính khách quan.","B":"Chỉ sử dụng câu trả lời nếu AI phản hồi với tốc độ nhanh và câu cú trôi chảy.","C":"Đối chiếu các mốc sự kiện và dữ liệu do AI cung cấp với sách giáo khoa và nguồn tài liệu chính thống.","D":"Yêu cầu AI dịch nội dung sang tiếng Anh rồi dịch ngược lại tiếng Việt để kiểm tra."},"answer":"C"},{"id":18,"type":"mcq","question":"Bác sĩ An nhận được kết quả chẩn đoán từ một phần mềm AI hỗ trợ phân tích ảnh chụp X-quang phổi: phần mềm cảnh báo có nốt mờ bất thường với độ tin cậy 88%. Tuy nhiên, khi đối chiếu hồ sơ bệnh án và triệu chứng lâm sàng của bệnh nhân, bác sĩ An nhận thấy chưa có dấu hiệu điển hình của bệnh lý đó. Trong trường hợp này, cách xử lý nào là phù hợp nhất theo đạo đức nghề nghiệp và nguyên tắc ứng dụng AI?","options":{"A":"Bỏ qua hoàn toàn kết quả chẩn đoán hình ảnh vì phần mềm AI không bao giờ chính xác bằng con người.","B":"Kê đơn điều trị ngay theo kết luận của AI để phòng ngừa nguy cơ xấu nhất.","C":"Yêu cầu bệnh nhân chuyển viện ngay mà không cần kiểm tra thêm.","D":"Xem kết quả của AI là thông tin tham khảo, chỉ định thêm xét nghiệm chuyên sâu cần thiết và tự mình đưa ra quyết định chẩn đoán cuối cùng."},"answer":"D"},{"id":19,"type":"mcq","question":"Anh Nam nhận được một video clip ngắn gửi qua ứng dụng nhắn tin từ tài khoản của người thân, trong video hình ảnh và giọng nói đều rất giống người thân đang nhờ chuyển tiền cấp cứu gấp vào một tài khoản ngân hàng lạ. Nhận thức được nguy cơ lừa đảo sử dụng công nghệ Deepfake, thao tác xác minh an toàn và hiệu quả nhất mà anh Nam nên làm ngay là:","options":{"A":"Chuyển trước một khoản tiền nhỏ vào tài khoản được cung cấp để kiểm tra tên chủ tài khoản.","B":"Gọi điện thoại trực tiếp qua mạng viễn thông thông thường (SIM) đến số điện thoại đã lưu của người thân đó để kiểm tra lại thông tin.","C":"Nhắn tin hỏi lại ngay trong ứng dụng chat xem có đúng là họ vừa gửi video không.","D":"Chụp ảnh màn hình video và dùng tính năng tìm kiếm bằng hình ảnh của Google."},"answer":"B"},{"id":20,"type":"mcq","question":"Một công ty sản xuất nước giải khát thường xuyên gặp tình trạng: vào mùa nắng nóng thì thiếu hụt hàng để phân phối, trong khi vào mùa mưa lại bị tồn kho quá nhiều khiến sản phẩm cận hạn sử dụng và phát sinh chi phí lưu kho lớn. Doanh nghiệp này nên triển khai giải pháp ứng dụng Trí tuệ nhân tạo (AI) nào sau đây để khắc phục hiệu quả nhất vấn đề trên?","options":{"A":"Triển khai hệ thống thị giác máy tính (Computer Vision) để kiểm tra khuyết tật vỏ chai trên băng chuyền đóng gói.","B":"Ứng dụng mô hình học máy (Machine Learning) phân tích dữ liệu bán hàng lịch sử, thời tiết và xu hướng thị trường để dự báo nhu cầu và tối ưu kế hoạch sản xuất, lưu kho.","C":"Trang bị robot tự hành để vận chuyển nguyên vật liệu tự động trong khuôn viên xưởng sản xuất.","D":"Tích hợp phần mềm trợ lý ảo (Chatbot) để tự động trả lời khiếu nại của khách hàng trên mạng xã hội."},"answer":"B"},{"id":21,"type":"mcq","question":"Trí tuệ nhân tạo (AI) là gì?","options":{"A":"Hệ thống máy tính có khả năng thực hiện các nhiệm vụ thông minh như con người.","B":"Một loại phần mềm chống vi-rút.","C":"Công cụ lập trình đơn giản.","D":"Phần mềm xử lý văn bản."},"answer":"A"},{"id":22,"type":"mcq","question":"Tính năng nhận dạng giọng nói của AI được ứng dụng ở đâu?","options":{"A":"Trợ lý ảo.","B":"Phần mềm văn phòng.","C":"Trò chơi điện tử.","D":"Máy tính cá nhân"},"answer":"A"},{"id":23,"type":"mcq","question":"Lợi ích của AI trong y tế là gì?","options":{"A":"Chẩn đoán bệnh nhanh chóng và chính xác.","B":"Giảm chi phí chăm sóc sức khỏe.","C":"Phát triển các phương pháp điều trị mới.","D":"Tất cả các lợi ích trên."},"answer":"D"},{"id":24,"type":"mcq","question":"Ứng dụng nào của AI là ứng dụng điển hình sử dụng trong lĩnh vực điều khiển.","options":{"A":"Hệ chuyên gia MYCIN.","B":"Robot Asimo.","C":"Google dịch.","D":"Trợ lý ảo."},"answer":"B"},{"id":25,"type":"mcq","question":"Deepfake là gì?","options":{"A":"Hình ảnh hoặc video giả mạo do ai tạo ra.","B":"Một loại phần mềm chỉnh sửa ảnh.","C":"Một thuật ngữ trong lập trình.","D":"Một công cụ tìm kiếm."},"answer":"A"},{"id":26,"type":"mcq","question":"Một hệ thống AI có thể có những khả năng nào?","options":{"A":"Có tri thức.","B":"Khả năng suy luận.","C":"Khả năng học.","D":"Tất cả các khả năng trên."},"answer":"D"},{"id":27,"type":"mcq","question":"Ví dụ về ứng dụng của AI trong đời sống là gì?","options":{"A":"Nhận dạng tiếng nói và khuôn mặt.","B":"Chơi game.","C":"Lướt web.","D":"Xem phim."},"answer":"A"},{"id":28,"type":"mcq","question":"Một cảnh báo về sự phát triển của AI trong tương lai là gì?","options":{"A":"Ai sẽ thay thế hoàn toàn con người.","B":"Ai sẽ gây ra nhiều vấn đề về đạo đức và an ninh.","C":"Ai sẽ giúp con người sống lâu hơn.","D":"Ai sẽ làm giảm tỷ lệ thất nghiệp​."},"answer":"B"},{"id":29,"type":"mcq","question":"Ví dụ minh hoạ cho một hệ thống AI có khả năng học là gì?","options":{"A":"Máy tính chơi cờ vua và tự học từ các trận đấu.","B":"Máy tính tính toán số liệu.","C":"Máy tính lướt web nhanh chóng.","D":"Máy tính ghi âm​​."},"answer":"A"},{"id":30,"type":"mcq","question":"Một cảnh báo về AI trong tương lai là gì?","options":{"A":"Ai có thể làm giảm nhu cầu lao động con người.","B":"Ai có thể tăng cường khả năng tự động hóa.","C":"Ai có thể giúp con người làm việc hiệu quả hơn.","D":"Ai có thể tạo ra nhiều cơ hội việc làm mới​​."},"answer":"A"},{"id":31,"type":"mcq","question":"Thiết bị nào sau đây được sử dụng để kết nối các thiết bị trong một mạng LAN?","options":{"A":"Modem.","B":"Switch.","C":"Router.","D":"Hub."},"answer":"B"},{"id":32,"type":"mcq","question":"Access Point có chức năng gì trong mạng không dây?","options":{"A":"Kết nối các thiết bị mạng với nhau.","B":"Phát sóng mạng không dây.","C":"Bảo mật mạng.","D":"Điều khiển truy cập mạng."},"answer":"B"},{"id":33,"type":"mcq","question":"Thiết bị nào sau đây được sử dụng để kiểm tra và lọc lưu lượng mạng?","options":{"A":"Switch.","B":"Router.","C":"Firewall.","D":"Access Point."},"answer":"C"},{"id":34,"type":"mcq","question":"Modem có chức năng gì trong mạng máy tính?","options":{"A":"Chuyển đổi tín hiệu số thành tín hiệu tương tự và ngược lại.","B":"Kết nối các máy tính trong mạng nội bộ.","C":"Điều khiển truy cập mạng.","D":"Lưu trữ dữ liệu."},"answer":"A"},{"id":35,"type":"mcq","question":"Giao thức mạng là gì?","options":{"A":"Một ngôn ngữ lập trình.","B":"Một loại phần mềm diệt virus.","C":"Bộ quy tắc và tiêu chuẩn dùng để truyền tải dữ liệu qua mạng.","D":"Một loại phần cứng mạng."},"answer":"C","answer_in_file":"A","corrected":true,"note":"Đáp án trong file là A (Một ngôn ngữ lập trình) – sai; đã sửa thành C, khớp với câu 109."},{"id":36,"type":"mcq","question":"Giao thức TCP/IP viết tắt của từ gì?","options":{"A":"Transmission Control Protocol/Internet Protocol.","B":"Transfer Control Protocol/Internet Protocol.","C":"Transmission Control Procedure/Internal Protocol.","D":"Transfer Control Procedure/Internal Protocol."},"answer":"A"},{"id":37,"type":"mcq","question":"Giao thức HTTP dùng để làm gì?","options":{"A":"Truyền tải email.","B":"Truyền tải tập tin.","C":"Truyền tải trang web.","D":"Truyền tải dữ liệu video."},"answer":"C"},{"id":38,"type":"mcq","question":"Giao thức nào được sử dụng để bảo mật các giao dịch trên web?","options":{"A":"HTTP.","B":"FTP.","C":"HTTPS.","D":"SMTP."},"answer":"C"},{"id":39,"type":"mcq","question":"Cho địa chỉ IP dưới dạng nhị phân 11000000 10101000 00001100 11010011 , hãy xác định địa chỉ ở dạng thập phân tương ứng?","options":{"A":"192.168.12.211.","B":"192.168.11.210.","C":"198.168.24.11.","D":"255.168.12.211."},"answer":"A"},{"id":40,"type":"mcq","question":"Để chia sẻ một thư mục trên mạng nội bộ, ta cần thực hiện thao tác nào trong Windows?","options":{"A":"Nhấp chuột phải vào thư mục, chọn \"Properties\", sau đó chọn tab \"Sharing\"..","B":"Nhấp chuột phải vào thư mục, chọn \"Delete\".","C":"Mở thư mục bằng Windows Media Player.","D":"Nhấp chuột phải vào thư mục, chọn \"Cut\"."},"answer":"A"},{"id":41,"type":"mcq","question":"Việc chia sẻ thông tin cá nhân như địa chỉ nhà, số điện thoại trên mạng xã hội có thể dẫn đến:","options":{"A":"Tăng cường mối quan hệ.","B":"Mất an toàn thông tin cá nhân.","C":"Nâng cao sự tín nhiệm.","D":"Tiếp cận với nhiều cơ hội hơn."},"answer":"B"},{"id":42,"type":"mcq","question":"Một trong những quy tắc quan trọng nhất khi giao tiếp trên mạng là:","options":{"A":"Chỉ cần quan tâm đến ý kiến của mình.","B":"Tôn trọng người khác và lắng nghe họ.","C":"Không cần chú ý đến ngữ pháp.","D":"Chỉ sử dụng tiếng lóng."},"answer":"B"},{"id":43,"type":"mcq","question":"Thuật ngữ AI được chính thức đề cập một cách khoa học ở đâu?","options":{"A":"Trong một công trình của nhà Toán học nổi tiếng A. Turing","B":"Tại Hội thảo Dartmouth năm 1956","C":"Trong Truyện cổ dân gian","D":"Trong nhiều công trình nghiên cứu được công bố trong nhiều năm khác nhau"},"answer":"B"},{"id":44,"type":"mcq","question":"Theo em, hiện tại AI không có khả năng nào sau đây?","options":{"A":"Dịch thuật;","B":"Phân biệt màu sắc;","C":"Làm thơ;","D":"Phân biệt mùi vị."},"answer":"D"},{"id":45,"type":"mcq","question":"Đặc trưng nào sau đây không là một trong những đặc trưng cơ bản của AI?","options":{"A":"Khả năng học","B":"Khả năng vận động","C":"Khả năng nhận thức","D":"Khả năng suy luận"},"answer":"B"},{"id":46,"type":"mcq","question":"Phương án nào là phương án ĐÚNG khi nói về sự khác nhau giữa Trí tuệ nhân tạo hẹp (AI hẹp) và Trí tuệ nhân tạo tổng quát (AI mạnh)?","options":{"A":"AI hẹp chỉ thực hiện một nhiệm vụ cụ thể","B":"AI mạnh thực hiện được một công việc giống như con người","C":"AI hẹp có khả năng tự học","D":"AI hẹp không thể ra quyết định"},"answer":"A"},{"id":47,"type":"mcq","question":"Phương án nào là phương án trả lời ĐÚNG khi nói về sự khác nhau giữa AI và tự động hoá?","options":{"A":"AI không thể đạt hiệu suất cao","B":"AI không thể thực hiện các thao tác lặp đi lặp lại một cách cơ học","C":"AI thể hiện các đặc trưng trí tuệ như con người","D":"AI có thể được sử dụng trong các dây chuyền lắp ráp"},"answer":"C"},{"id":48,"type":"mcq","question":"Trong y học, AI không được sử dụng để:","options":{"A":"Cải thiện chất lượng hình ảnh y tế","B":"Hỗ trợ chẩn đoán và điều trị","C":"Chế tạo thuốc điều trị mới","D":"Thực hiện các phẫu thuật y khoa một cách độc lập"},"answer":"D"},{"id":49,"type":"mcq","question":"Ứng dụng nào sau đây không phải của AI trong ngành tài chính?","options":{"A":"Phân tích dữ liệu đầu tư","B":"Phát hiện và ngăn chặn gian lận","C":"Tự động hoá quá trình sản xuất","D":"Tự động hoá cập nhật chứng từ"},"answer":"C"},{"id":50,"type":"mcq","question":"Bên cạnh những lợi ích to lớn, sự phát triển của AI KHÔNG kéo theo nguy cơ cần được cảnh báo nào?","options":{"A":"Áp lực thất nghiệp","B":"Các Hệ chuyên gia ngày càng thông minh","C":"Ảnh hưởng quyền riêng tư","D":"Rủi ro về an ninh, an toàn"},"answer":"B"},{"id":51,"type":"mcq","question":"Cách nào sau đây KHÔNG là cách bảo vệ sự phát triển của AI trong tương lai?","options":{"A":"Đảm bảo tính minh bạch và trách nhiệm giải trình trong việc phát triển và sử dụng AI","B":"Không cần kiểm soát sự phát triển của AI","C":"Thiết lập các nguyên tắc đạo đức cho việc phát triển và sử dụng AI","D":"Khuyến khích nghiên cứu và phát triển AI vì mục đích tiến bộ chung của xã hội."},"answer":"B"},{"id":52,"type":"mcq","question":"Theo bạn, điều gì KHÔNG là thách thức đối với việc đảm bảo sự phát triển AI vì lợi ích cộng đồng?","options":{"A":"Giải quyết các vấn đề đạo đức liên quan đến AI. B. Đảm bảo AI không gây ra thất nghiệp hàng loạt. AI tạo ra những công việc đòi hỏi những năng lực và kĩ năng nghề nghiệp mới. Duy trì sự kiểm soát của con người đối với AI.","B":"Đảm bảo AI không gây ra thất nghiệp hàng loạt.","C":"AI tạo ra những công việc đòi hỏi những năng lực và kĩ năng nghề nghiệp mới","D":"Duy trì sự kiểm soát của con người đối với AI."},"answer":"D"},{"id":53,"type":"mcq","question":"Khả năng học của AI là gì?","options":{"A":"Trích xuất thông tin từ dữ liệu để học và tích lũy tri thức","B":"Cảm nhận và hiểu biết môi trường thông qua các cảm biến và thiết bị đầu vào","C":"Khả năng vận dụng logic và tri thức để đưa ra quyết định hoặc kết luận.","D":"Khả năng tìm ra cách giải quyết các tình huống phức tạp dựa trên thông tin và tri thức"},"answer":"A"},{"id":54,"type":"mcq","question":"Hiện nay Trí tuệ nhân tạo KHÔNG có đặc trưng nào?","options":{"A":"Khả năng học và tích lũy tri thức","B":"Khả năng hiểu ngôn ngữ của con người","C":"Khả năng cảm nhận và thấu hiểu cảm xúc của con người một cách trọn vẹn","D":"Khả năng giải quyết vấn đề"},"answer":"C"},{"id":55,"type":"mcq","question":"Điều nào sau đây là sai?","options":{"A":"Switch có thể thay được hub trong mọi trường hợp.","B":"Switch chỉ có thể thay thế cho hub khi số thiết bị mạng lớn hay tần suất sử dụng mạng cao","C":"Trong mạng gia đình có ít thiết bị, không cần dùng switch","D":"Hub không thể thay thế cho switch trong mọi trường hợp"},"answer":"B"},{"id":56,"type":"mcq","question":"Trước khi chia sẻ tài nguyên trong mạng cục bộ, nên thiết lập một số chế độ. Thiết lập nào không cần thiết?","options":{"A":"Thiết lập chế độ mạng riêng (private)","B":"Thiết lập trạng thái cho các máy tính khác nhìn thấy (discoverable) cho phép chia sẻ tệp và máy in","C":"Huỷ bỏ việc phải đăng nhập vào vào máy cho chia sẻ tài nguyên","D":"Tắt tạm thời tường lửa"},"answer":"B"},{"id":57,"type":"mcq","question":"Thiết bị nào dưới đây có chức năng “Biến đổi dữ liệu số từ các thiết bị kết nối mạng thành tín hiệu tương tự để truyền đi và ngược lại”?","options":{"A":"Laptop","B":"Modem","C":"Switch","D":"Access point"},"answer":"B","answer_in_file":"C","corrected":true,"note":"Đáp án trong file là C (Switch) – sai; chức năng điều chế/giải điều chế là của Modem (B)."},{"id":58,"type":"mcq","question":"Thiết bị nào dưới đây giúp kết nối các thiết bị mạng tạo thành mạng hình sao?","options":{"A":"Laptop","B":"Modem","C":"Switch","D":"Access point"},"answer":"C"},{"id":59,"type":"mcq","question":"Ngoài chức năng kết nối không dây, Access point thường được tích hợp  thêm chức năng nào dưới đây?","options":{"A":"Mở rộng băng thông","B":"Điều chế tín hiệu","C":"Giải điều chế tín hiệu","D":"Định tuyến"},"answer":"D"},{"id":60,"type":"mcq","question":"Ngoài việc kết nối các thiết bị theo mô hình mạng hình sao, Switch còn có chức năng nào dưới đây?","options":{"A":"Giảm thiểu xung đột tín hiệu để mạng hoạt động ổn định","B":"Điều chế","C":"Giải điều chế","D":"Phát Wi-Fi"},"answer":"A"},{"id":61,"type":"mcq","question":"Điều gì dưới đây đảm bảo cho các máy tính và thiết bị mạng có thể giao tiếp được với nhau đúng cách?","options":{"A":"Giao thức mạng (Network protocol)","B":"Giao tiếp mạng (Network communication)","C":"Giao dịch mạng (Network transactions)","D":"Giao thông mạng (Network traffic)"},"answer":"A"},{"id":62,"type":"mcq","question":"Giao thức mạng nói chung KHÔNG yêu cầu điều gì dưới đây đối với thiết bị gửi?","options":{"A":"Xác định địa chỉ thiết bị nhận","B":"Đóng gói dữ liệu","C":"Giải nén dữ liệu","D":"Truyền gói dữ liệu"},"answer":"C"},{"id":63,"type":"mcq","question":"Giao thức mạng nói chung  KHÔNG yêu cầu điều gì đối với thiết bị nhận?","options":{"A":"Đóng gói dữ liệu","B":"Kiểm tra địa chỉ","C":"Kiểm tra tính đúng đắn của dữ liệu nhận được","D":"Mã hóa dữ liệu nhận được"},"answer":"A"},{"id":64,"type":"mcq","question":"Trong giao thức mạng, yêu cầu nào dưới đây được đặt ra trên cả thiết bị gửi và thiết bị nhận?","options":{"A":"Đóng gói dữ liệu","B":"Giải nén dữ liệu","C":"Mã hóa dữ liệu để đảm bảo an toàn","D":"Kiểm tra, xử lí lỗi và đảm bảo độ tin cậy"},"answer":"D"},{"id":65,"type":"mcq","question":"Những yêu cầu nào KHÔNG thuộc phạm vi của giao thức mạng tại máy tính gửi dữ liệu :","options":{"A":"Xác định địa chỉ nơi nhận","B":"Đóng gói dữ liệu để chuyển đi","C":"Xác định đường đi đúng cho gói dữ liệu","D":"Truyền gói dữ liệu"},"answer":"C"},{"id":66,"type":"mcq","question":"Trong những yêu cầu sau, yêu cầu nào liên quan đến giao thức mạng:","options":{"A":"Xác định các lĩnh vực mà AI đang phát triển","B":"Giới thiệu lịch sử của máy tính","C":"Thảo luận về mạng Internet","D":"Trình bày về các phần mềm văn phòng"},"answer":"A","needs_review":true,"note":"Câu bị lỗi trong file gốc: đáp án A (lĩnh vực AI) lệch đề, và có đoạn văn thừa dính vào phương án D (\"Học ngành CNTT ChatGPT là ví dụ của loại trí tuệ nhân tạo nào?\"). Cần kiểm tra lại với giáo viên."},{"id":67,"type":"mcq","question":"Một trong những cảnh báo về AI là gì?","options":{"A":"AI có thể thay thế hoàn toàn con người trong mọi công việc","B":"AI sẽ không bao giờ phát triển hơn nữa","C":"AI có thể gây nguy hiểm nếu không được kiểm soát","D":"AI không có khả năng học hỏiTìm Giáo Án"},"answer":"C"},{"id":68,"type":"mcq","question":"Ứng dụng nào của AI trong y tế được đề cập trong tài liệu?","options":{"A":"Chẩn đoán bệnh","B":"Quản lý dữ liệu bệnh viện","C":"Đo chiều cao","D":"Kiểm soát chất lượng thực phẩm"},"answer":"A"},{"id":69,"type":"mcq","question":"ChatGPT là gì?","options":{"A":"Một hệ điều hành","B":"Một chatbot được huấn luyện","C":"Một phần mềm diệt virus","D":"Một trình duyệt web"},"answer":"B"},{"id":70,"type":"mcq","question":"Tác giả bài học cho rằng AI có thể trở nên thông minh hơn con người không?","options":{"A":"Không","B":"Có, trong một số lĩnh vực cụ thể","C":"Có, trong tất cả các lĩnh vực","D":"Không có ý kiếnHọc khoa học"},"answer":"B"},{"id":71,"type":"mcq","question":"AI có thể được sử dụng để phát triển hệ thống giao thông thông minh không?","options":{"A":"Không","B":"Có","C":"Chỉ trong các thành phố lớn","D":"Chỉ trong các khu vực nông thôn"},"answer":"B"},{"id":72,"type":"mcq","question":"Một trong những rủi ro tiềm tàng của việc phát triển AI là gì?","options":{"A":"Thiếu nguồn nhân lực","B":"Không đủ dữ liệu","C":"Sử dụng AI cho mục đích xấu","D":"Thiếu khả năng tài chính"},"answer":"C"},{"id":73,"type":"mcq","question":"AI có thể giúp cải thiện chất lượng chăm sóc y tế bằng cách nào?","options":{"A":"Chẩn đoán bệnh nhanh chóng","B":"Tăng chi phí y tế","C":"Giảm số lượng bác sĩ","D":"Xóa bỏ hoàn toàn bệnh tậtTra từ điển chuẩn"},"answer":"A"},{"id":74,"type":"mcq","question":"AI có thể áp dụng trong lĩnh vực vận tải như thế nào?","options":{"A":"Tự động lái xe","B":"Quản lý kho bãi","C":"Tăng cường dịch vụ khách hàng","D":"Giảm tốc độ giao thông"},"answer":"A"},{"id":75,"type":"mcq","question":"ChatGPT được huấn luyện trên gì?","options":{"A":"Dữ liệu ngẫu nhiên","B":"Dữ liệu lớn từ Internet","C":"Dữ liệu tài chính","D":"Dữ liệu lịch sửHọc toán online"},"answer":"B"},{"id":76,"type":"mcq","question":"AI có thể hỗ trợ quyết định trong lĩnh vực nào?","options":{"A":"Kinh doanh","B":"Giáo dục","C":"Y tế","D":"Tất cả các lĩnh vực trên"},"answer":"D"},{"id":77,"type":"mcq","question":"Một trong những ứng dụng của AI trong cuộc sống hàng ngày là gì?","options":{"A":"Tăng chi phí sinh hoạt","B":"Giải quyết các bài toán phức tạp","C":"Tự động phát nhạc","D":"Giảm sự sáng tạo của con ngườiTìm Giáo Án"},"answer":"C"},{"id":78,"type":"mcq","question":"ChatGPT có thể làm gì?","options":{"A":"Tạo văn bản theo yêu cầu","B":"Điều khiển robot","C":"Thực hiện phẫu thuật","D":"Dạy học"},"answer":"A"},{"id":79,"type":"mcq","question":"Phương án nào sau đây nêu đúng một ứng dụng tiêu biểu của AI trong lĩnh vực sản xuất và điều hành công nghiệp?","options":{"A":"Hỗ trợ phẫu thuật nội soi thông qua cánh tay robot.","B":"Dự báo nhu cầu thị trường và tối ưu hóa quản lý hàng tồn kho.","C":"Chấm điểm phát âm chuẩn xác cho người học ngoại ngữ.","D":"Tự động tìm kiếm và trích dẫn tài liệu tham khảo cho bài tiểu luận."},"answer":"B"},{"id":80,"type":"mcq","question":"Khi sử dụng các hệ thống AI tạo sinh (như chatbot hoặc công cụ sinh văn bản), người dùng cần lưu ý hiện tượng 'ảo giác' (hallucination) của AI là gì?","options":{"A":"Hệ thống bị virus xâm nhập và làm hỏng hệ điều hành máy tính.","B":"AI tự ngắt kết nối mạng khi người dùng đặt câu hỏi quá khó.","C":"AI tự tạo ra thông tin không có thật nhưng được trình bày rất tự tin và trôi chảy.","D":"AI tự động đánh cắp mật khẩu và thông tin cá nhân của người dùng."},"answer":"C"},{"id":81,"type":"mcq","question":"Một trong những cảnh báo về tác động tiêu cực của AI đối với an ninh thông tin và đời sống xã hội là:","options":{"A":"AI làm cạn kiệt nguồn tài nguyên điện năng của toàn cầu ngay lập tức.","B":"Công nghệ Deepfake có thể bị kẻ xấu lợi dụng để tạo ra hình ảnh, âm thanh, video giả mạo nhằm lừa đảo.","C":"AI làm tốc độ truy cập Internet toàn cầu bị chậm đi đáng kể.","D":"AI khiến cho các thiết bị lưu trữ số (ổ cứng, thẻ nhớ) bị giảm dung lượng vật lý."},"answer":"B"},{"id":82,"type":"mcq","question":"Phương án nào sau đây nêu đúng một ứng dụng tiêu biểu của Trí tuệ nhân tạo trong lĩnh vực giao thông vận tải?","options":{"A":"Tối ưu hóa chu kỳ đèn tín hiệu dựa trên mật độ phương tiện thực tế.","B":"Hỗ trợ chẩn đoán tổn thương mô phổi qua ảnh chụp cắt lớp vi tính.","C":"Chấm điểm ngữ điệu phát âm tự động cho người học ngoại ngữ.","D":"Dự báo nhu cầu tiêu thụ sản phẩm và kiểm soát hàng tồn kho."},"answer":"A"},{"id":83,"type":"mcq","question":"Xét theo phân loại khả năng của Trí tuệ nhân tạo, công cụ ChatGPT hiện nay thuộc loại nào sau đây?","options":{"A":"AI tổng quát (AGI).","B":"AI hẹp (ANI).","C":"Siêu AI (ASI).","D":"AI có ý thức độc lập."},"answer":"B"},{"id":84,"type":"mcq","question":"Trong lĩnh vực y tế, Trí tuệ nhân tạo phát huy hiệu quả hỗ trợ đội ngũ bác sĩ chủ yếu nhờ vào khả năng nào sau đây?","options":{"A":"Tự động điều chỉnh thiết bị chẩn đoán mà không cần nhân viên y tế thao tác.","B":"Tự động kê đơn thuốc và chỉ định phác đồ điều trị thay thế quyết định của bác sĩ.","C":"So sánh, phân tích các dấu hiệu bất thường trên hình ảnh y tế (chụp X-quang, CT, MRI) dựa trên cơ sở dữ liệu bệnh án khổng lồ.","D":"Thay thế hoàn toàn nhân lực y tế trong các khâu phẫu thuật và chăm sóc bệnh nhân."},"answer":"C"},{"id":85,"type":"mcq","question":"Việc ứng dụng AI để 'cá nhân hóa học tập' trong giáo dục được thể hiện rõ nhất qua khả năng nào sau đây của hệ thống dạy học thông minh?","options":{"A":"Tự động nhận diện khuôn mặt để điểm danh học sinh khi bước vào phòng học.","B":"Tự động theo dõi tiến độ, phân tích điểm mạnh - điểm yếu của từng người học để đề xuất nội dung và bài tập phù hợp.","C":"Thay thế hoàn toàn giáo viên trong việc giảng dạy toàn bộ chương trình học.","D":"Soạn sẵn một giáo án cố định duy nhất dùng chung cho tất cả các đối tượng học sinh."},"answer":"B"},{"id":86,"type":"mcq","question":"Một trong những rủi ro lớn về mặt đạo đức và xã hội khi ứng dụng các mô hình AI dự đoán và ra quyết định tự động là gì?","options":{"A":"Hệ thống AI có thể đưa ra kết quả thiên vị, thiếu công bằng nếu tập dữ liệu dùng để huấn luyện mang định kiến sẵn có.","B":"Các mô hình AI luôn hoạt động chậm dần theo thời gian sử dụng.","C":"Trí tuệ nhân tạo khiến con người không thể sử dụng mạng máy tính Internet.","D":"AI chỉ có thể hoạt động chính xác nếu không sử dụng đến dữ liệu số."},"answer":"A"},{"id":87,"type":"mcq","question":"Khác với các thiết bị cơ khí truyền thống, các robot y tế tích hợp AI (như hệ thống hỗ trợ phẫu thuật Da Vinci) mang lại lợi ích nổi bật nào trong phòng mổ?","options":{"A":"Giúp phẫu thuật viên thực hiện các thao tác siêu vi phẫu với độ chuẩn xác, ổn định cao và hạn chế xâm lấn tối đa.","B":"Tự động lập kế hoạch mổ và tiến hành phẫu thuật mà không cần sự có mặt của kíp mổ.","C":"Loại bỏ hoàn toàn mọi rủi ro y khoa trong suốt quá trình phẫu thuật.","D":"Chỉ đóng vai trò ghi hình ca mổ phục vụ cho việc lưu trữ hồ sơ bệnh án."},"answer":"A"},{"id":88,"type":"mcq","question":"Nhận định nào sau đây phản ánh đầy đủ và khách quan nhất về tác động của Trí tuệ nhân tạo đối với thị trường lao động xã hội?","options":{"A":"AI sẽ loại bỏ hoàn toàn nhu cầu lao động của con người ở mọi ngành nghề trong tương lai gần.","B":"AI hoàn toàn không làm thay đổi số lượng hay tính chất của các ngành nghề truyền thống.","C":"AI làm giảm nhu cầu lao động đối với các công việc lặp đi lặp lại mang tính thủ công, đồng thời mở ra các ngành nghề mới đòi hỏi kỹ năng cao hơn.","D":"AI chỉ tác động tiêu cực đến những người làm việc trực tiếp trong ngành công nghệ thông tin."},"answer":"C"},{"id":89,"type":"mcq","question":"Bác sĩ Lan phụ trách đọc phim X-quang tại một bệnh viện mỗi ngày phải xử lý hơn 200 ca chụp phổi, dẫn đến nguy cơ bỏ sót các tổn thương nhỏ do mệt mỏi. Để hỗ trợ giảm tải công việc và hạn chế tối đa sai sót chẩn đoán, giải pháp công nghệ nào sau đây là phù hợp nhất?","options":{"A":"Thay thế bác sĩ Lan bằng robot tự động ra quyết định phẫu thuật.","B":"Sử dụng phần mềm AI ứng dụng thị giác máy tính để khoanh vùng sơ bộ các nốt mờ bất thường trên ảnh chụp trước khi bác sĩ thẩm định.","C":"Nâng cấp máy in phim X-quang để tăng tốc độ in kết quả giấy.","D":"Chuyển toàn bộ hồ sơ bệnh án sang dạng tệp nén để tiết kiệm bộ nhớ lưu trữ của máy tính."},"answer":"B"},{"id":90,"type":"mcq","question":"Hệ thống máy chủ của một ngân hàng mỗi giây tiếp nhận hàng triệu lượt yêu cầu truy cập. Đội ngũ an ninh mạng nhận thấy phương pháp thiết lập tường lửa bằng các quy tắc tĩnh truyền thống không thể bắt kịp các đợt tấn công từ chối dịch vụ và mã độc biến thể mới. Doanh nghiệp này nên ứng dụng giải pháp nào sau đây?","options":{"A":"Triển khai mô hình học máy (Machine Learning) để liên tục phân tích hành vi lưu lượng truy cập bất thường và tự động kích hoạt cảnh báo, ngăn chặn theo thời gian thực.","B":"Tăng băng thông đường truyền Internet của nhà mạng lên gấp đôi.","C":"Yêu cầu nhân viên an ninh mạng kiểm tra thủ công nhật ký truy cập (log) của từng người dùng vào cuối ngày.","D":"Tắt toàn bộ hệ thống máy chủ vào ban đêm khi ít người giao dịch."},"answer":"A"},{"id":91,"type":"mcq","question":"Một sàn thương mại điện tử nhận thấy tỷ lệ khách hàng rời bỏ trang web mà không mua hàng rất cao vì danh mục hàng hóa quá lớn khiến người mua khó tìm được món đồ ưng ý. Để tăng tỷ lệ chuyển đổi đơn hàng và cá nhân hóa trải nghiệm mua sắm, sàn thương mại này nên áp dụng giải pháp nào?","options":{"A":"Gửi email quảng cáo đồng loạt tất cả sản phẩm mới cho toàn bộ người dùng vào mỗi sáng.","B":"Triển khai hệ thống gợi ý dựa trên AI để phân tích lịch sử tìm kiếm, giỏ hàng và đề xuất các sản phẩm phù hợp với sở thích của từng cá nhân.","C":"Giảm số lượng mặt hàng hiển thị trên trang chủ xuống còn 5 sản phẩm bán chạy nhất.","D":"Yêu cầu người dùng phải điền một bản khảo sát chi tiết trước khi được phép xem sản phẩm."},"answer":"B"},{"id":92,"type":"mcq","question":"Một tòa nhà văn phòng cao ốc 30 tầng tiêu tốn lượng điện năng rất lớn cho hệ thống điều hòa không khí do nhiệt độ cài đặt cố định cả ngày, bất kể thời tiết bên ngoài hay số lượng người có mặt trong từng phòng. Giải pháp ứng dụng AI nào sau đây giúp tối ưu hóa tiêu thụ năng lượng hiệu quả nhất?","options":{"A":"Tắt hẳn hệ thống điều hòa trong các giờ làm việc cao điểm.","B":"Cài đặt hệ thống AI kết hợp cảm biến IoT để tự động dự đoán và điều chỉnh nhiệt độ làm mát linh hoạt theo mật độ người và nhiệt độ môi trường thời gian thực.","C":"Thay đổi giao diện phần mềm điều khiển sang chế độ nền tối (Dark mode) để tiết kiệm màn hình máy tính.","D":"Lắp đặt thêm quạt công nghiệp tại tất cả các hành lang."},"answer":"B"},{"id":93,"type":"mcq","question":"Một công ty tài chính muốn xét duyệt các khoản vay tiêu dùng nhỏ cho khách hàng trong vòng 5 phút mà vẫn đảm bảo kiểm soát tốt rủi ro nợ xấu, thay vì mất từ 3-5 ngày thẩm định hồ sơ giấy tờ truyền thống. Giải pháp ứng dụng AI nào sau đây là phù hợp nhất?","options":{"A":"Xây dựng mô hình AI chấm điểm tín nhiệm tự động dựa trên phân tích dữ liệu lịch sử thanh toán, chi tiêu và dòng tiền của khách hàng.","B":"Phê duyệt tự động cho tất cả khách hàng nộp đơn mà không cần kiểm tra lịch sử tài chính.","C":"Giảm lãi suất vay về mức 0% để kích thích khách hàng hoàn tiền đúng hạn.","D":"Thuê thêm nhiều nhân viên thẩm định trực tiếp tại quầy vào ca đêm."},"answer":"A"},{"id":94,"type":"mcq","question":"Thiết bị nào sau đây là thiết bị mạng?","options":{"A":"Máy in","B":"Router","C":"Màn hình","D":"Bàn phím"},"answer":"B"},{"id":95,"type":"mcq","question":"Thiết bị nào sau đây có chức năng chính là điều chế và giải điều chế tín hiệu để kết nối mạng nội bộ với Internet?","options":{"A":"Switch","B":"Hub","C":"Modem","D":"Access Point"},"answer":"C"},{"id":96,"type":"mcq","question":"Access point có chức năng nào sau đây?","options":{"A":"Kết nối các thiết bị qua mạng có dây.","B":"Tạo mạng không dây nội bộ và kết nối các thiết bị không dây vào mạng LAN.","C":"Đóng vai trò trung tâm trong mạng hình sao.","D":"Chuyển đổi tín hiệu tương tự thành dữ liệu số."},"answer":"B"},{"id":97,"type":"mcq","question":"Router có chức năng chính nào sau đây?","options":{"A":"Kết nối các thiết bị bằng sóng vô tuyến trong mạng cục bộ.","B":"Tìm đường đi tối ưu để truyền các gói dữ liệu giữa các mạng.","C":"Chuyển đổi giữa tín hiệu tương tự và tín hiệu số qua mạng.","D":"Phát tín hiệu đến tất cả các cổng kết nối trong mạng LAN."},"answer":"B"},{"id":98,"type":"mcq","question":"Một doanh nghiệp muốn kết nối các máy tính trong văn phòng của họ vào một mạng LAN. Thiết bị nào họ nên sử dụng?","options":{"A":"Router","B":"Modem","C":"Switch","D":"Hub"},"answer":"C"},{"id":99,"type":"mcq","question":"Một mạng LAN được mở rộng để kết nối với một mạng khác ở vị trí xa. Thiết bị nào nên được sử dụng để kết nối hai mạng này?","options":{"A":"Hub","B":"Router","C":"Switch","D":"Access Point"},"answer":"B"},{"id":100,"type":"mcq","question":"Modem thường được đặt ở vị trí nào trong sơ đồ mạng gia đình?","options":{"A":"Giữa máy tính và switch","B":"Giữa mạng nội bộ và nhà cung cấp dịch vụ Internet (ISP)","C":"Giữa các máy tính trong mạng LAN","D":"Giữa Access Point và máy in"},"answer":"B"},{"id":101,"type":"mcq","question":"LAN là loại mạng nào sau đây?","options":{"A":"Mạng cục bộ.","B":"Mạng diện rộng.","C":"Mạng toàn cầu.","D":"Mạng thành phố."},"answer":"A"},{"id":102,"type":"mcq","question":"Trong mạng nội bộ trường học, Switch thường được đặt ở đâu?","options":{"A":"Nơi tập trung dây mạng từ các phòng học để kết nối về Router/Modem","B":"Ở giữa các Access Point","C":"Giữa máy tính và máy in","D":"Giữa Router và ISP"},"answer":"A"},{"id":103,"type":"mcq","question":"Switch có chức năng chính nào sau đây?","options":{"A":"Thiết lập các kết nối để truyền dữ liệu trong mạng LAN.","B":"Thiết lập kết nối không dây giữa các thiết bị trong mạng.","C":"Định tuyến cho gói dữ liệu khi truyền đi giữa các mạng.","D":"Chuyển từ tín hiệu số sang tín hiệu tương tự và ngược lại."},"answer":"A"},{"id":104,"type":"mcq","question":"Một ưu điểm của giao thức TCP là gì?","options":{"A":"Không có khả năng kiểm soát lỗi.","B":"Đảm bảo truyền tải dữ liệu đáng tin cậy và theo đúng thứ tự.","C":"Không hỗ trợ việc định địa chỉ và định tuyến.","D":"Không có khả năng mở rộng."},"answer":"B"},{"id":105,"type":"mcq","question":"Một trong những hạn chế của bộ giao thức TCP/IP là gì?","options":{"A":"Thiếu tính linh hoạt khi mở rộng quy mô mạng.","B":"Không hỗ trợ định tuyến cho các mạng khác nhau.","C":"Chưa tích hợp sẵn cơ chế bảo mật chặt chẽ ở các tầng cơ bản.","D":"Hoàn toàn không kiểm tra lỗi truyền dẫn trên đường truyền."},"answer":"C"},{"id":106,"type":"mcq","question":"Khi một email được gửi đi, giao thức nào được sử dụng để gửi email đó từ máy người gửi đến máy chủ email?","options":{"A":"FTP","B":"HTTP","C":"TCP","D":"SMTP"},"answer":"D"},{"id":107,"type":"mcq","question":"Nếu một công ty muốn chia sẻ tập tin lớn giữa các chi nhánh, họ nên sử dụng giao thức nào?","options":{"A":"HTTP","B":"FTP","C":"SMTP","D":"POP3"},"answer":"B"},{"id":108,"type":"mcq","question":"Trong một hệ thống mạng, làm thế nào để đảm bảo rằng dữ liệu không bị mất trong quá trình truyền tải?","options":{"A":"Sử dụng giao thức UDP","B":"Sử dụng giao thức TCP","C":"Sử dụng giao thức HTTP","D":"Sử dụng giao thức SMTP"},"answer":"B"},{"id":109,"type":"mcq","question":"Giao thức mạng là gì?","options":{"A":"Tập hợp các quy tắc để xác định cách định dạng, truyền và nhận dữ liệu.","B":"Thiết bị dùng để kết nối mạng không dây.","C":"Phần cứng dùng để chuyển đổi dữ liệu số thành tín hiệu tương tự.","D":"Một loại phần mềm quản lý mạng LAN."},"answer":"A"},{"id":110,"type":"mcq","question":"FTP là giao thức gì?","options":{"A":"Giao thức truyền tải tập tin","B":"Giao thức truyền tải email","C":"Giao thức truyền tải dữ liệu","D":"Giao thức truyền tải trang web"},"answer":"A"},{"id":111,"type":"mcq","question":"Giao thức/dịch vụ nào có chức năng chuyển đổi tên miền (ví dụ: [www.google.com](https://www.google.com)) thành địa chỉ IP tương ứng để máy tính có thể kết nối?","options":{"A":"FTP","B":"HTTP","C":"DNS","D":"SMTP"},"answer":"C"},{"id":112,"type":"mcq","question":"Trong hệ thống gửi và nhận email: Giao thức nào thường dùng để gửi thư đi và nhận thư về?","options":{"A":"HTTP và HTTPS","B":"FTP và POP3","C":"SMTP và POP3","D":"HTTPS và FTP"},"answer":"C"},{"id":113,"type":"mcq","question":"Một trang web bán hàng trực tuyến yêu cầu người dùng nhập thông tin thẻ tín dụng. Trang này nên sử dụng giao thức nào?","options":{"A":"HTTP","B":"HTTPS","C":"FTP","D":"POP3"},"answer":"B"},{"id":114,"type":"mcq","question":"Trong quá trình thiết lập môi trường để chia sẻ tệp và máy in trong mạng cục bộ trên Windows, mục đích của việc tạm thời tắt tường lửa (Windows Defender Firewall) là gì?","options":{"A":"Để tăng tốc độ in ấn tài liệu qua mạng.","B":"Tránh việc tường lửa ngăn chặn các máy tính khác truy cập tài nguyên chia sẻ từ bên ngoài.","C":"Để tự động cấp quyền chỉnh sửa (read/write) cho toàn bộ người dùng trong mạng.","D":"Để máy tính tự động cài đặt trình điều khiển cho máy in mới."},"answer":"B"},{"id":115,"type":"mcq","question":"Khi thiết lập môi trường chia sẻ trên Windows, chế độ mạng nào sau đây được khuyến nghị lựa chọn để các máy tính tin cậy có thể nhìn thấy nhau và chia sẻ tài nguyên an toàn?","options":{"A":"Public network","B":"Private network","C":"Guest network","D":"Airplane mode"},"answer":"B"},{"id":116,"type":"mcq","question":"Để chia sẻ thư mục trên MAY_1, bước nào sau đây là đúng?","options":{"A":"Chọn thư mục, nhấp chuột phải, chọn Properties, sau đó chọn Sharing","B":"Chọn thư mục, nhấp chuột phải, chọn Share","C":"Mở thư mục, sau đó chọn Share","D":"Chọn thư mục, sau đó chọn Add to Network"},"answer":"A"},{"id":117,"type":"mcq","question":"Sau khi tìm thấy máy in cần chia sẻ, bạn làm gì tiếp theo để chia sẻ nó?","options":{"A":"Chọn máy in, sau đó chọn Share","B":"Chọn máy in, sau đó chọn Printer properties và thiết lập chia sẻ","C":"Nhấp chuột phải lên máy in, chọn Share","D":"Kết nối máy in với máy tính khác"},"answer":"B"},{"id":118,"type":"mcq","question":"Lựa chọn cho phép bật tính năng chia sẻ tệp và máy in là:","options":{"A":"Turn on password protected sharing","B":"Turn off network discovery","C":"Turn on file and printer sharing","D":"Turn off file and printer sharing"},"answer":"C"},{"id":119,"type":"mcq","question":"Lựa chọn cho phép tắt tính năng chia sẻ bằng mật khẩu là:","options":{"A":"Turn on password protected sharing","B":"Turn off password protected sharing","C":"Turn on file and printer sharing","D":"Turn off file and printer sharing"},"answer":"B"},{"id":120,"type":"mcq","question":"Cách làm nào sau đây là đúng khi muốn chia sẻ ổ đĩa cho người dùng khác trong cùng mạng để đọc, xem dữ liệu?","options":{"A":"Nháy phải chuột ổ đĩa cần chia sẻ/Properties/Advanced Sharing, chọn nhóm hoặc tên người dùng cần chia sẻ, chọn mức phân quyền Full control.","B":"Nháy phải chuột ổ đĩa cần chia sẻ/Properties/Advanced Sharing, chọn nhóm hoặc tên người dùng cần chia sẻ, chọn mức phân quyền Change.","C":"Nháy phải chuột ổ đĩa cần chia sẻ/Properties/Advanced Sharing, chọn nhóm hoặc tên người dùng cần chia sẻ, chọn mức phân quyền Read.","D":"Nháy phải chuột ổ đĩa cần chia sẻ/Properties/Advanced Sharing, chọn nhóm hoặc tên người dùng cần chia sẻ, chọn cả 3 mức phân quyền Full control, Change, Read."},"answer":"C"},{"id":121,"type":"mcq","question":"Khi phân quyền truy cập cho thư mục dùng chung, để người dùng từ máy khác vừa xem được nội dung vừa có thể chỉnh sửa, thêm hoặc xóa tệp tin, ta cần cấp quyền nào sau đây?","options":{"A":"Read","B":"Read/Write","C":"Remove","D":"View only"},"answer":"B"},{"id":122,"type":"mcq","question":"Trong một mạng LAN có máy tính X được kết nối trực tiếp với máy in qua dây cáp. Để tất cả các máy tính trong mạng sử dụng được máy in này, công việc nào sau đây không nhất thiết phải thực hiện?","options":{"A":"Cài đặt máy in (đã được máy tính X chia sẻ) cho các máy tính còn lại.","B":"Chia sẻ quyền truy cập máy in qua mạng trên máy tính X.","C":"Cài đặt trình điều khiển máy in cho máy tính X.","D":"Chia sẻ thư mục chứa trình điều khiển máy in trên máy tính X."},"answer":"D"},{"id":123,"type":"mcq","question":"Sau khi một thư mục trên máy tính được thiết lập chia sẻ thành công, khi các máy tính khác trong mạng mở xem qua File Explorer, biểu tượng của thư mục đó có đặc điểm nhận diện nào sau đây?","options":{"A":"Có thêm dấu khóa màu đỏ ở góc dưới bên phải.","B":"Có hình chữ nhật màu xanh lá phía dưới, tượng trưng cho dây cáp mạng.","C":"Tên thư mục tự động đổi sang màu xanh da trời.","D":"Có biểu tượng mũi tên quay tròn màu vàng."},"answer":"B"},{"id":124,"type":"mcq","question":"Giao tiếp trong không gian mạng giúp mở rộng kết nối xã hội như thế nào?","options":{"A":"Không gian mạng cung cấp nhiều công cụ giao tiếp trực tuyến như hội nghị truyền hình, nhắn tin nhanh, thư điện tử, mạng xã hội, ...","B":"Những người sống xa nhau có thể giao tiếp với nhau mọi lúc, mọi nơi, miễn là có kết nối mạng.","C":"Điện thoại video giúp con người gần nhau hơn khi không có điều kiện sống cùng nhau.","D":"Giúp xây dựng thương hiệu cá nhân hoặc doanh nghiệp bằng cách thông qua các kênh truyền thông xã hội, tạo ấn tượng tốt để thu hút khách hàng và bạn bè."},"answer":"D"},{"id":125,"type":"mcq","question":"Vì sao lại nói giao tiếp trong không gian mạng ẩn chứa nhiều nguy cơ về bảo mật và quyền riêng tư?","options":{"A":"Trong không gian mạng, người sử dụng có thể dễ dàng giấu mặt, tạo ra các bản sao không đầy đủ của bản thân hoặc giả mạo thông tin, làm cho người khác khó đánh giá được tính chân thật của thông tin và sự thật về người đối diện.","B":"Mất kết nối mạng dẫn đến giao tiếp bị trì hoãn hoặc bị gián đoạn.","C":"Dữ liệu bị xâm phạm khiến các thông tin riêng tư và nhạy cảm bị rò rỉ hoặc bị tấn công bởi những kẻ xấu.","D":"Thư điện tử hay tin nhắn có thể gây khó khăn trong việc truyền đạt cảm xúc và dẫn đến những hiểu lầm không đáng có."},"answer":"C"},{"id":126,"type":"mcq","question":"“Chia sẻ thông tin chính xác và đáng tin cậy, tránh lan truyền thông tin sai lệch hoặc tin đồn” thể hiện khía cạnh nào trong việc ứng xử nhân văn trong không gian mạng?","options":{"A":"Lịch sự.","B":"Thấu hiểu.","C":"Tôn trọng.","D":"Hỗ trợ."},"answer":"A"},{"id":127,"type":"mcq","question":"Em cần làm gì để hình thành thói quen ứng xử nhân văn trong không gian mạng?","options":{"A":"Đối xử với người khác theo cách mà mình muốn.","B":"Tự kiểm điểm, cải thiện hành vi trực tuyến của mình.","C":"Làm theo ý muốn cá nhân, không tôn trọng ý kiến của người khác.","D":"Sử dụng ngôn từ và cách viết tuỳ hứng."},"answer":"B"},{"id":128,"type":"mcq","question":"Khi tham một cuộc thảo luận trên mạng xã hội, em cần ứng xử như thế nào?","options":{"A":"Tự ý trao đổi thông tin riêng tư trong thư điện tử giữa hai người với bên thứ ba.","B":"Mặc quần áo lịch sự và không để lộ những vật dụng hoặc cảnh quan không phù hợp.","C":"Sử dụng ngôn từ khiêu khích khi không đồng tình với ý kiến của người khác.","D":"Nếu có ý kiến trái ngược, cần trao đổi một cách lịch sự trên tinh thần tôn trọng quan điểm của người khác."},"answer":"D"},{"id":129,"type":"mcq","question":"Trong nhóm học tập trực tuyến, một thành viên thường xuyên gửi hàng loạt tin nhắn đùa cợt ngoài lề, gửi ảnh chế liên tục làm trôi các thông báo quan trọng của giáo viên. Hành vi này thể hiện điều gì?","options":{"A":"Tinh thần cởi mở, tạo không khí vui tươi cho nhóm học tập.","B":"Thiếu tôn trọng người khác, gửi tin nhắn vô thưởng vô phạt gây phiền toái.","C":"Sự hỗ trợ kịp thời giúp các bạn giải tỏa căng thẳng học đường.","D":"Vi phạm nghiêm trọng an ninh mạng dẫn tới mất quyền kiểm soát nhóm."},"answer":"B"},{"id":130,"type":"mcq","question":"Khi đọc một bài viết chia sẻ quan điểm phương pháp ôn thi trên mạng xã hội, Lan nhận thấy ý kiến của tác giả hoàn toàn trái ngược với thói quen học tập của mình. Cách xử sự nào sau đây là văn minh nhất?","options":{"A":"Dùng lời lẽ gay gắt bình luận để bác bỏ quan điểm của tác giả ngay lập tức.","B":"Chụp ảnh màn hình đăng lên trang cá nhân kèm lời chê bai để bạn bè cùng công kích.","C":"Đọc kỹ nội dung, bình tĩnh phân tích và bình luận trao đổi lịch sự trên tinh thần tôn trọng góc nhìn của tác giả.","D":"Kêu gọi các thành viên khác báo cáo bài viết để ban quản trị xóa bài."},"answer":"C"},{"id":131,"type":"mcq","question":"Tuấn nhận được email từ bạn thân tâm sự về chuyện gia đình đang gặp khó khăn. Một bạn khác trong lớp tò mò và gặng hỏi, xin Tuấn chuyển tiếp (forward) nội dung email để xem. Hành động đúng đắn của Tuấn là gì?","options":{"A":"Chuyển tiếp email ngay để bạn cùng lớp cùng tìm cách giúp đỡ.","B":"Chụp ảnh màn hình che tên người gửi rồi đăng lên nhóm kín xin ý kiến.","C":"Kiên quyết từ chối chia sẻ nội dung email vì cần tôn trọng quyền riêng tư và thư tín của bạn.","D":"Kể tóm tắt lại nội dung câu chuyện cho cả lớp nghe trong giờ ra chơi."},"answer":"C"},{"id":132,"type":"mcq","question":"Trong buổi thảo luận hoặc học tập trực tuyến qua phần mềm có bật camera (video call), hành động nào sau đây thể hiện tính lịch sự và văn hóa số đúng chuẩn?","options":{"A":"Mặc trang phục ngủ cho thoải mái vì đang ngồi học trong không gian phòng ngủ của mình.","B":"Để camera quay vào khu vực bừa bộn, để người nhà qua lại tự do trước ống kính.","C":"Mặc trang phục gọn gàng, điều chỉnh camera tránh lộ cảnh quan không phù hợp và giữ thái độ chú ý đúng mực.","D":"Vừa tham gia học vừa bật nhạc nền to để tạo không khí sôi nổi cho phòng học."},"answer":"C"},{"id":133,"type":"mcq","question":"Sau khi vô tình đăng bình luận trêu chọc một người bạn trên mạng xã hội khiến bạn cảm thấy bị tổn thương, Nam rất hối hận. Để thể hiện sự tự kiểm tra và cải thiện hành vi trực tuyến, Nam nên làm gì?","options":{"A":"Khóa hoặc xóa tài khoản cá nhân để lảng tránh vấn đề.","B":"Cho rằng đối phương quá nhạy cảm và không cần phải bận tâm.","C":"Chủ động gỡ bỏ bình luận, nhắn tin hoặc gặp trực tiếp xin lỗi chân thành và rút kinh nghiệm cẩn trọng ngôn từ.","D":"Nhắn tin yêu cầu bạn giữ im lặng, không được chia sẻ sự việc với thầy cô hoặc phụ huynh."},"answer":"C"},{"id":134,"type":"tf","question":"Hiện nay, ứng dụng AI được sử dụng trong rất nhiều lĩnh vực. Nhận định nào sau đây là đúng, nhận định nào sai khi nói về AI?","statements":[{"key":"a","text":"AI có thể thay thế hoàn toàn công việc của con người trong tất cả các lĩnh vực."},{"key":"b","text":"Khả năng học của AI là khả năng nắm bắt thông tin từ dữ liệu và điều chỉnh hành vi dựa trên thông tin mới."},{"key":"c","text":"Một trong những thách thức của AI là vấn đề đạo đức."},{"key":"d","text":"Chatbot là một loại robot vật lý."}],"answerString":"SĐĐS","answer":[false,true,true,false]},{"id":135,"type":"tf","question":"Nhận định về giao thức mạng:","statements":[{"key":"a","text":"Giao thức mạng là bộ quy tắc dùng để truyền tải dữ liệu qua mạng."},{"key":"b","text":"TCP là giao thức tầng ứng dụng."},{"key":"c","text":"FTP dùng để truyền tải email."},{"key":"d","text":"HTTPS là phiên bản bảo mật của HTTP."}],"answerString":"ĐSSĐ","answer":[true,false,false,true]},{"id":136,"type":"tf","question":"Trong một giờ học, các bạn trong lớp cần kết nối laptop để chiếu nội dung thuyết trình lên màn hình tivi. Các bạn có một số nhận xét về việc kết nối các thiết bị với máy tính như sau:","statements":[{"key":"a","text":"Để kết nối máy tính Laptop với tivi, cần phải có dây cáp mới kết nối được."},{"key":"b","text":"Khi đã chiếu được nội dung lên màn hình tivi, chúng ta có thể tắt máy tính, việc trình chiếu nội dung bài vẫn thực hiện bình thường."},{"key":"c","text":"Khi kết nối bằng dây cáp, cần sử dụng dây kết nối có cổng phù hợp với cổng có sẵn trên máy tính và ti vi."},{"key":"d","text":"Khi truyền bằng Bluetooth, ti vi và máy tính ở xa nhau vẫn không bị ảnh hưởng đến hiệu quả kết nối."}],"answerString":"SSĐS","answer":[false,false,true,false]},{"id":137,"type":"tf","question":"Các bạn trong lớp 12A đang thực hành chia sẻ các máy tính trong phòng Tin.","statements":[{"key":"a","text":"Tất cả các thiết bị trong mạng phải có cùng địa chỉ IP để có thể kết nối với nhau, máy khách tùy thuộc vào tình huống."},{"key":"b","text":"Việc chia sẻ tài nguyên chỉ nên thực hiện trên mạng không dây để tránh rắc rối về cáp mạng."},{"key":"c","text":"Chia sẻ tài nguyên trên mạng không cần phải thiết lập quyền truy cập."},{"key":"d","text":"Chúng ta có thể sử dụng các tệp dữ liệu được chia sẻ trên mạng LAN như các tệp dữ liệu trên máy tính của mình."}],"answerString":"ĐSSĐ","answer":[true,false,false,true]},{"id":138,"type":"tf","question":"Xét tình huống gửi dữ liệu qua Internet:","statements":[{"key":"a","text":"Giao thức mạng quy định cách thức giao tiếp giữa các đối tượng truyền nhận dữ liệu."},{"key":"b","text":"Khi hai máy không cùng LAN, router hỗ trợ chuyển tiếp dữ liệu dựa trên IP."},{"key":"c","text":"Nếu gói đến không có mục trong bảng định tuyến tĩnh nhưng có cổng mặc định, router có thể chuyển theo cổng mặc định."},{"key":"d","text":"Nếu máy nhận ở LAN khác, máy gửi có thể bỏ qua router vì chỉ cần biết MAC của máy nhận từ đầu."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":139,"type":"tf","question":"Đánh dấu đúng hoặc sai về một số lĩnh vực nghiên cứu phát triển AI?","statements":[{"key":"a","text":"Học máy là lĩnh vực nghiên cứu làm cho máy tính có khả năng học từ dữ liệu thu được."},{"key":"b","text":"Xử lý ngôn ngữ tự nhiên là nghiên cứu các mô hình ngôn ngữ để máy tính và con người giao tiếp với nhau"},{"key":"c","text":"Thị giác máy tính là lĩnh vực nghiên cứu phương pháp thu nhận và phân tích nhận dạng hình ảnh"},{"key":"d","text":"AI hẹp là AI có khả năng tự học từ dữ liệu mới."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":140,"type":"tf","question":"AI đang phát triển nhanh chóng và ứng dụng vào hầu hết các lĩnh vực như giáo dục, y tế, tài chính, nông nghiệp, giao thông,…","statements":[{"key":"a","text":"Nhận dạng khuôn mặt phổ biến trong rất nhiều ứng dụng: sử dụng khuôn mặt để mở khoá điện thoại thông minh, xác thực khuôn mặt trong các ứng dụng ngân hàng thông minh, điểm danh trong các ứng dụng học trực tuyến."},{"key":"b","text":"Trợ lí ảo được xây dựng để nhận dạng và hiểu giọng nói của con người."},{"key":"c","text":"Các nhà khoa học tại Viện Công nghệ Massachusetts đã tạo ra ứng dụng Sybil dựa trên AI để phát hiện dấu hiệu bệnh ung thư máu."},{"key":"d","text":"Nhiều ứng dụng dạy ngôn ngữ sử dụng AI và nhận dạng khuôn mặt để đánh giá khả năng ngôn ngữ của người học"}],"answerString":"ĐĐSS","answer":[true,true,false,false]},{"id":141,"type":"tf","question":"Hiện nay, ứng dụng AI được sử dụng trong rất nhiều lĩnh vực. Nhận định nào sau đây là đúng, nhận định nào sai khi nói về AI?","statements":[{"key":"a","text":"AI có thể thay thế hoàn toàn công việc của con người trong tất cả các lĩnh vực."},{"key":"b","text":"Khả năng học của AI là khả năng nắm bắt thông tin từ dữ liệu và điều chỉnh hành vi dựa trên thông tin mới."},{"key":"c","text":"Mô hình AI trong lĩnh vực thị giác máy tính cho phép các thiết bị thông minh nhận dạng chữ viết tay."},{"key":"d","text":"Trợ lý ảo là một công nghệ AI được xây dựng để nhận dạng và hiểu giọng nói của con người"}],"answerString":"SĐĐĐ","answer":[false,true,true,true]},{"id":142,"type":"tf","question":"AI đã có những tác động mạnh mẽ trong các lĩnh vực khoa học công nghệ và đời sống.","statements":[{"key":"a","text":"AI có thể thay thế hoàn toàn công việc của con người trong tất cả các lĩnh vực."},{"key":"b","text":"Khả năng học của AI là khả năng nắm bắt thông tin từ dữ liệu và điều chỉnh hành vi dựa trên thông tin mới."},{"key":"c","text":"Mô hình AI trong lĩnh vực thị giác máy tính cho phép các thiết bị thông minh nhận dạng chữ viết tay."},{"key":"d","text":"Trợ lý ảo là một công nghệ AI được xây dựng để nhận dạng và hiểu giọng nói của con người"}],"answerString":"ĐSSĐ","answer":[true,false,false,true]},{"id":143,"type":"tf","question":"Có những cảnh báo về AI trong tương lai. Hãy đánh dấu Đúng hoặc Sai cho các phát biểu sau:","statements":[{"key":"a","text":"AI giúp cải thiện dịch vụ nhằm thu hút và nâng cao trải nghiệm của khách hàng."},{"key":"b","text":"Các hệ thống AI trong y tế có thể thay thế hoàn toàn bác sĩ trong quá trình chẩn đoán"},{"key":"c","text":"AI không có vai trò gì trong lĩnh vực tài chính"},{"key":"d","text":"AI có khả năng giải quyết các vấn đề phức tạp trong lập trình"}],"answerString":"ĐSĐS","answer":[true,false,true,false]},{"id":144,"type":"tf","question":"Khi so sánh về đặc điểm và chức năng giữa Switch và Hub trong mạng LAN, mỗi nhận định sau đây là Đúng hay Sai?","statements":[{"key":"a","text":"Dữ liệu huấn luyện thiên vị có thể gây ra các vấn đề đạo đức trong AI."},{"key":"b","text":"AI hoàn toàn không ảnh hưởng đến quyền riêng tư cá nhân"},{"key":"c","text":"AI có thể tạo ra các cuộc tấn công mạng thông minh và khó bị phát hiện."},{"key":"d","text":"AI chỉ tạo ra công việc mới mà không thay thế các công việc hiện tại."}],"answerString":"SSĐS","answer":[false,false,true,false]},{"id":145,"type":"tf","question":"Tòa nhà của một công ty có một số phòng làm việc. Mỗi phòng có không quá 10 máy tính, được kết nối với nhau thông qua Switch tạo thành một mạng LAN. Công ty cần kết nối các mạng LAN này với nhau để tạo thành một mạng cục bộ duy nhất. Sau khi thảo luận, một số nhân viên của công ty đưa ra các nhận định sau:","statements":[{"key":"a","text":"Switch là thiết bị chuyên dùng cho mạng không dây, trong khi Hub chỉ dùng cho mạng có dây."},{"key":"b","text":"Hub có khả năng kiểm tra địa chỉ và chuyển tiếp dữ liệu có chọn lọc, còn Switch gửi dữ liệu đồng thời đến tất cả các cổng."},{"key":"c","text":"Switch chuyển tiếp khung dữ liệu đến đúng cổng của thiết bị nhận, trong khi Hub phát tán tín hiệu đến tất cả các cổng còn lại"},{"key":"d","text":"Hub có tốc độ truyền tải nhanh hơn và khả năng bảo mật thông tin cao hơn so với Switch"}],"answerString":"SĐSĐ","answer":[false,true,false,true]},{"id":146,"type":"tf","question":"Một gia đình chuyển đến căn nhà mới có bốn tầng. Họ được nhà cung cấp dịch vụ viễn thông lắp đặt một Modem để sử dụng Internet trong nhà. Các thành viên trong gia đình thường sử dụng điện thoại thông minh để truy cập Internet, tuy nhiên, tín hiệu Internet không ổn định tại một số phòng. Hơn nữa, gia đình còn có nhu cầu sử dụng Internet trên các máy tính để bàn không có chức năng kết nối mạng không dây. Các thành viên trong gia đình đã đưa ra các ý kiến sau:","statements":[{"key":"a","text":"Việc truy cập Internet bằng điện thoại thông minh mà không dùng dữ liệu mạng di động chứng tỏ Modem của gia đình đã được tích hợp chức năng phát Wi-Fi"},{"key":"b","text":"Để tránh tình trạng tín hiệu Internet không ổn định trong một số phòng, có thể dùng thêm Access Point để kết nối với Modem và đặt Access Point này ở vị trí gần các phòng đó."},{"key":"c","text":"Nếu gia đình muốn sử dụng Internet bằng máy tính để bàn thì cách đơn giản nhất là dùng cáp mạng để kết nối giữa máy tính đó với Modem."},{"key":"d","text":"Để tất cả các máy tính để bàn truy cập được Internet, gia đình cần kết nối các máy tính đó với nhau thông qua một Switch nhưng không kết nối Switch với Modem"}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":147,"type":"tf","question":"Chọn đúng hoặc sai cho từng câu sau về giao thức mạng và TCP/IP:","statements":[{"key":"a","text":"Giao thức TCP/IP bao gồm hai phần chính là TCP và UDP."},{"key":"b","text":"Giao thức TCP đảm bảo việc truyền dữ liệu tin cậy, không bị mất mát và đúng thứ tự."},{"key":"c","text":"Giao thức HTTP được sử dụng để gửi email giữa các thiết bị."},{"key":"d","text":"Giao thức HTTPS có lớp mã hóa giúp truyền dữ liệu an toàn."}],"answerString":"SĐSĐ","answer":[false,true,false,true]},{"id":148,"type":"tf","question":"Khi nói về vai trò và đặc điểm của giao thức IP (Internet Protocol) trong bộ giao thức TCP/IP, mỗi nhận định sau đây là Đúng hay Sai?","statements":[{"key":"a","text":"IP chịu trách nhiệm kiểm tra lỗi dữ liệu trên đường truyền và tự động yêu cầu gửi lại các gói tin bị mất mát."},{"key":"b","text":"Vai trò chính của IP là đánh địa chỉ logic và định tuyến các gói tin từ thiết bị gửi đến thiết bị nhận qua các mạng khác nhau."},{"key":"c","text":"Giao thức IP tích hợp sẵn cơ chế mã hóa dữ liệu mặc định để bảo mật các giao dịch thanh toán trực tuyến của người dùng."},{"key":"d","text":"IP hoạt động ở tầng Mạng (Internet/Network layer) và không thiết lập kênh truyền kết nối chuyên biệt (connectionless) trước khi gửi dữ liệu."}],"answerString":"SĐSĐ","answer":[false,true,false,true]},{"id":149,"type":"tf","question":"Các phát biểu sau đúng hay sai khi thực hiện chia sẻ và sử dụng tài nguyên dùng chung trong mạng cục bộ trên Windows?","statements":[{"key":"a","text":"Để chia sẻ ổ đĩa, người dùng nhấp chuột phải vào ổ đĩa, chọn Properties, vào thẻ Sharing, chọn Advanced Sharing và kích hoạt tính năng chia sẻ."},{"key":"b","text":"Để chia sẻ một thư mục, người dùng nhấp chuột phải vào thư mục đó, chọn Properties, rồi chọn thẻ Sharing."},{"key":"c","text":"Khi chia sẻ ổ đĩa qua mạng, người dùng không thể thiết lập phân quyền truy cập cho các tài khoản hoặc nhóm người dùng khác."},{"key":"d","text":"Máy tính kết nối trực tiếp với máy in không cần cài đặt trình điều khiển (driver) vẫn có thể chia sẻ máy in đó cho toàn mạng."}],"answerString":"ĐĐSS","answer":[true,true,false,false]},{"id":150,"type":"tf","question":"Khi thực hiện chia sẻ máy in và sử dụng máy in mạng trong hệ điều hành Windows, các phát biểu sau là Đúng hay Sai?","statements":[{"key":"a","text":"Máy tính kết nối trực tiếp với máy in đóng vai trò là máy chủ cung cấp dịch vụ in (Print Server)."},{"key":"b","text":"Các máy tính khác trong mạng chỉ có thể in được nếu máy tính chia sẻ máy in đang bật và kết nối mạng."},{"key":"c","text":"Để chia sẻ máy in, người dùng mở thẻ Sharing trong cửa sổ Printer properties và chọn Share this printer."},{"key":"d","text":"Khi kết nối máy in dùng chung qua mạng, người dùng bắt buộc phải nhập chính xác địa chỉ MAC của máy in đó. (Sai - chỉ cần duyệt tìm tên máy tính chia sẻ hoặc tên máy in)"}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":151,"type":"tf","question":"Để nhóm học sinh có thể vừa xem tài liệu, vừa nộp bài tập và sửa đổi nội dung tệp tin trong thư mục dùng chung DỰ ÁN trên mạng cục bộ, mỗi nhận định sau đây là Đúng hay Sai?","statements":[{"key":"a","text":"Người quản trị cần thiết lập mức phân quyền là Read cho nhóm học sinh."},{"key":"b","text":"Người quản trị cần thiết lập mức phân quyền là Read/Write cho nhóm học sinh."},{"key":"c","text":"Người quản trị nên bật tính năng bảo vệ bằng mật khẩu (Turn on password protected sharing) nhưng không cần cung cấp tài khoản cho học sinh."},{"key":"d","text":"Việc thiết lập phân quyền chia sẻ được thực hiện thông qua thẻ Sharing trong cửa sổ Properties của thư mục DỰ ÁN."}],"answerString":"SĐSĐ","answer":[false,true,false,true]},{"id":152,"type":"tf","question":"Trong bối cảnh hội nhập toàn cầu hiện nay, sự bùng nổ của công nghệ thông tin và truyền thông đã góp phần thay đổi phương thức giao tiếp trong xã hội.","statements":[{"key":"a","text":"Không gian mạng cho phép con người giao tiếp với nhau thông qua các phần mềm và dịch vụ giao tiếp trực tuyến như mạng xã hội, thư giấy, ứng dụng nhắn tin, gọi điện thoại video,…"},{"key":"b","text":"Giao tiếp trực tuyến có thể được thực hiện mọi nơi, mọi lúc, miễn là có kết nối mạng."},{"key":"c","text":"Giao tiếp trong không gian mạng có thể gây khó khăn trong việc truyền đạt cảm xúc và dẫn đến những hiểu lầm không đáng có."},{"key":"d","text":"“Tránh gửi nội dung thư rác hoặc quảng cáo không liên quan đến nội dung chính của cuộc trò chuyện” thể hiện khía cạnh tôn trọng trong việc ứng xử nhân văn trong không gian mạng."}],"answerString":"SĐĐS","answer":[false,true,true,false]},{"id":153,"type":"tf","question":"Một người lạ nhắn tin bắt chuyện qua mạng xã hội và giới thiệu cơ hội “việc nhẹ lương cao” cho một học sinh. Tuy nhiên, người này yêu cầu học sinh phải chuyển khoản trước một số tiền đặt cọc để giữ chỗ nhận việc. Để đảm bảo an toàn cho bản thân trên không gian mạng, mỗi nhận định sau đây về cách ứng xử của bạn học sinh là Đúng hay Sai?","statements":[{"key":"a","text":"Nộp ngay khoản tiền đặt cọc theo yêu cầu để không bỏ lỡ cơ hội việc làm hấp dẫn."},{"key":"b","text":"Chủ động xác minh kỹ thông tin về doanh nghiệp hoặc đối tượng tuyển dụng qua các kênh chính thống trước khi đưa ra quyết định."},{"key":"c","text":"Bỏ qua tin nhắn, chặn liên hệ từ tài khoản lạ và cảnh báo cho bạn bè, người thân về dấu hiệu lừa đảo tương tự."},{"key":"d","text":"Nếu nhận thấy dấu hiệu lừa đảo chiếm đoạt tài sản rõ ràng, học sinh nên thu thập bằng chứng tin nhắn và cùng gia đình trình báo cho cơ quan công an."}],"answerString":"SĐĐĐ","answer":[false,true,true,true]},{"id":154,"type":"tf","question":"Xét việc truyền dữ liệu bằng TCP:","statements":[{"key":"a","text":"TCP có cấp số hiệu cổng ứng dụng."},{"key":"b","text":"TCP đánh số gói để ở nơi nhận có thể ráp lại đúng thứ tự theo từng ứng dụng."},{"key":"c","text":"Nếu gói thứ 2 đến trước gói thứ 1, cơ chế đánh số của TCP giúp nhận biết thứ tự để ráp lại."},{"key":"d","text":"Vì TCP có đánh số gói nên dữ liệu luôn đi qua cùng một router và chắc chắn không thể có gói đến khác thứ tự."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":155,"type":"tf","question":"Xét địa chỉ và truyền dữ liệu trong LAN:","statements":[{"key":"a","text":"IPv4 được viết theo kiểu dot decimal, các byte ở dạng thập phân và cách nhau bằng dấu chấm."},{"key":"b","text":"MAC được mô tả là địa chỉ 6 byte gắn với phần cứng."},{"key":"c","text":"Nếu hai máy cùng LAN, theo bài chỉ cần địa chỉ MAC để máy nhận xác định các gói dành cho mình."},{"key":"d","text":"Nếu hai máy khác LAN, địa chỉ MAC của máy nhận ngoài LAN phải được máy gửi xác định trực tiếp từ đầu thì router mới chuyển được."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":156,"type":"tf","question":"Xét DNS và ICMP:","statements":[{"key":"a","text":"DNS cho phép dùng tên bằng chữ thay cho địa chỉ IP khó nhớ."},{"key":"b","text":"Ping dùng ICMP để kiểm tra kết nối giữa các thiết bị."},{"key":"c","text":"Khi người dùng gõ tên miền trong lệnh ping, tên miền có thể thay cho địa chỉ IP theo chức năng DNS được nêu trong bài."},{"key":"d","text":"Vì ping dùng ICMP nên ping có chức năng thay thế TCP trong việc đảm bảo dữ liệu ứng dụng đến đúng thứ tự."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":157,"type":"tf","question":"Xét IP, MAC và LAN:","statements":[{"key":"a","text":"IPv4 thường viết 4 byte dạng thập phân cách nhau bằng dấu chấm."},{"key":"b","text":"MAC là địa chỉ gắn với phần cứng."},{"key":"c","text":"Cùng LAN có thể dùng MAC để nhận đúng máy đích."},{"key":"d","text":"Khác LAN thì máy gửi luôn biết sẵn MAC máy nhận từ đầu mà không cần router."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":158,"type":"tf","question":"Xét TCP:","statements":[{"key":"a","text":"TCP kiểm soát truyền dữ liệu."},{"key":"b","text":"TCP có thể yêu cầu gửi lại khi mất gói."},{"key":"c","text":"Đánh số gói giúp ráp đúng thứ tự."},{"key":"d","text":"TCP bảo đảm mọi gói luôn đi cùng một đường và không bao giờ lệch thứ tự."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":159,"type":"tf","question":"Xét TCP và ứng dụng:","statements":[{"key":"a","text":"TCP cấp cho mỗi ứng dụng một số hiệu gọi là cổng ứng dụng."},{"key":"b","text":"Cổng ứng dụng giúp các gói dữ liệu được gắn nhãn để không lẫn giữa các ứng dụng."},{"key":"c","text":"Nếu hai ứng dụng cùng truyền dữ liệu, việc gắn cổng ứng dụng giúp phân biệt dữ liệu theo ứng dụng."},{"key":"d","text":"Vì có cổng ứng dụng nên TCP không cần đánh số gói và không cần cơ chế xác nhận."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":160,"type":"tf","question":"Xét Ethernet và truyền gói:","statements":[{"key":"a","text":"Ethernet có quy định về khung truyền tín hiệu."},{"key":"b","text":"Việc giới hạn độ dài gói giúp tránh một lượng tin dài không giới hạn gây quá tải máy nhận."},{"key":"c","text":"Khi nhiều cuộc truyền được tách thành các gói, các cuộc truyền có thể xen kẽ trên cùng đường truyền vật lí."},{"key":"d","text":"Việc chia thành gói khiến mỗi cuộc truyền phải độc chiếm đường truyền vật lí trong suốt thời gian truyền."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":161,"type":"tf","question":"Xét các giao thức thư điện tử:","statements":[{"key":"a","text":"SMTP là giao thức được nêu cho việc gửi thư."},{"key":"b","text":"POP3 hoặc IMAP là các giao thức được nêu cho việc người nhận lấy thư."},{"key":"c","text":"Nếu người gửi nhập sai địa chỉ người nhận, máy chủ thư có thể tạo thư báo lỗi chuyển ngược lại người gửi."},{"key":"d","text":"POP3/IMAP được dùng để thay thế router trong việc định tuyến thư giữa các mạng."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":162,"type":"tf","question":"Xét DNS và ping:","statements":[{"key":"a","text":"ICMP được dùng trong lệnh ping theo bài."},{"key":"b","text":"DNS cho phép dùng tên bằng chữ thay cho địa chỉ IP khó nhớ."},{"key":"c","text":"Khi ping theo tên miền, tên miền có thể được dùng thay cho IP theo chức năng DNS được nêu."},{"key":"d","text":"Nếu ping không có Echo Reply thì chắc chắn máy đích không tồn tại trên mạng."}],"answerString":"ĐĐĐS","answer":[true,true,true,false]},{"id":163,"type":"short","question":"Chuyển dãy bit 11000000 10101000 00000001 00000011 sang địa chỉ IPv4 dạng thập phân.","answer":["192.168.1.3"],"note":"Câu này không có trong file Word; lấy từ bản tóm tắt trước đó nên đề được viết lại.","source":"summary"},{"id":164,"type":"short","question":"Cho tên miền example.com. Theo cách phân lớp tên miền, hãy xác định tên miền cấp cao nhất (TLD)","answer":[".com","com"]},{"id":165,"type":"short","question":"Cho tên miền blog.example.com. Hãy xác định subdomain","answer":["blog"]},{"id":166,"type":"short","question":"Chuyển dãy bit 00001010 00011001 00000000 11111111 sang địa chỉ IPv4 dạng thập phân.","answer":["10.25.0.255"],"note":"Câu này không có trong file Word; lấy từ bản tóm tắt trước đó nên đề được viết lại.","source":"summary"},{"id":167,"type":"short","question":"Một người dùng muốn gửi một email đến người khác. Trong ba giao thức SMTP, POP3, IMAP, giao thức nào được sử dụng cho hoạt động gửi email?","answer":["SMTP"]},{"id":168,"type":"short","question":"Cho tên miền www.example.com. Giao thức nào có chức năng chuyển đổi tên miền dễ nhớ thành địa chỉ IP để máy tính có thể xác định máy chủ cần truy cập?","answer":["DNS"]},{"id":169,"type":"short","question":"Nền tảng AI nào do OpenAI phát triển, có khả năng trò chuyện và hỗ trợ tạo nội dung?","answer":["ChatGPT"]},{"id":170,"type":"short","question":"Công nghệ AI nào của Google có thể hỗ trợ người dùng tìm kiếm thông tin, tạo nội dung và giải đáp câu hỏi?","answer":["Gemini"]},{"id":171,"type":"short","question":"Trợ lý AI nào do Anthropic phát triển, có thể hỗ trợ viết nội dung, phân tích tài liệu và lập trình?","answer":["Claude"]},{"id":172,"type":"short","question":"Trợ lý AI nào do công ty xAI phát triển, gắn liền với nền tảng mạng xã hội X?","answer":["Grok"]}];
